// Function to read Excel file
function readExcelFile(filePath) {
    const buffer = fs.readFileSync(filePath);
    const workbook = xlsx.read(buffer, { type: 'buffer' });
    const sheetName = workbook.SheetNames[0]; // Assume first sheet
    const worksheet = workbook.Sheets[sheetName];
    return xlsx.utils.sheet_to_json(worksheet);
}

// Function to compare two Excel files
function compareExcelFiles(file1, file2) {
    const data1 = readExcelFile(file1);
    const data2 = readExcelFile(file2);

    const discrepancies = [];

    // Compare each row
    for (let i = 0; i < Math.max(data1.length, data2.length); i++) {
        const row1 = data1[i] || {};
        const row2 = data2[i] || {};

        // Compare each cell in the row
        for (const key in row1) {
            if (row1[key] !== row2[key]) {
                discrepancies.push({
                    row: i + 1, // Rows are 1-indexed
                    column: key,
                    value1: row1[key],
                    value2: row2[key]
                });
            }
        }
    }

    return discrepancies;
}

